import{H as e,V as t,et as n,j as r}from"./chunks/framework.DKIRGhFK.js";import{av as i,ov as a,sv as o}from"./chunks/assets.CUKu7Ix7.js";var s=JSON.parse(`{"title":"生命周期","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/react/lifecycle.md","filePath":"frontend/react/lifecycle.md"}`),c={name:`frontend/react/lifecycle.md`};function l(r,s,c,l,u,d){return n(),t(`div`,null,[...s[0]||=[e(`<h1 id="生命周期" tabindex="-1">生命周期 <a class="header-anchor" href="#生命周期" aria-label="Permalink to “生命周期”">​</a></h1><h2 id="生命周期-概述" tabindex="-1">生命周期 - 概述 <a class="header-anchor" href="#生命周期-概述" aria-label="Permalink to “生命周期 - 概述”">​</a></h2><p>组件的生命周期是指组件从被创建到挂载到页面中运行起来，再到组件不用时卸载的过程，注意，只有类组件才有生命周期（类组件 实例化 函数组件 不需要实例化）<br><img src="`+o+`" alt="" width="723" height="275"><br><a href="http://projects.wojtekmaj.pl/react-lifecycle-methods-diagram/" target="_blank" rel="noreferrer">详细生命周期</a></p><h2 id="生命周期-挂载阶段" tabindex="-1">生命周期 - 挂载阶段 <a class="header-anchor" href="#生命周期-挂载阶段" aria-label="Permalink to “生命周期 - 挂载阶段”">​</a></h2><p><img src="`+a+`" alt="" width="723" height="173"></p><table tabindex="0"><thead><tr><th>钩子函数</th><th>触发时机</th><th>作用</th></tr></thead><tbody><tr><td>constructor</td><td>创建组件时，最先执行，初始化的时候只执行一次</td><td>1. 初始化state 2. 创建 Ref 3. 使用 bind 解决 this 指向问题等</td></tr><tr><td>render</td><td>每次组件渲染都会触发</td><td>渲染UI（注意： 不能在里面调用setState() ）</td></tr><tr><td>componentDidMount</td><td>组件挂载（完成DOM渲染）后执行，初始化的时候执行一次</td><td>1. 发送网络请求 2.DOM操作</td></tr></tbody></table><h2 id="生命周期-更新阶段" tabindex="-1">生命周期 - 更新阶段 <a class="header-anchor" href="#生命周期-更新阶段" aria-label="Permalink to “生命周期 - 更新阶段”">​</a></h2><p><img src="`+i+`" alt="" width="723" height="142"></p><table tabindex="0"><thead><tr><th>钩子函数</th><th>触发时机</th><th>作用</th></tr></thead><tbody><tr><td>render</td><td>每次组件渲染都会触发</td><td>渲染UI（与 挂载阶段 是同一个render）（注意： 不能在里面调用setState() ）</td></tr><tr><td>componentDidUpdate</td><td>组件更新后（DOM渲染完毕）</td><td>DOM操作，可以获取到更新后的DOM内容，不要直接调用setState</td></tr></tbody></table><h2 id="生命周期-卸载阶段" tabindex="-1">生命周期 - 卸载阶段 <a class="header-anchor" href="#生命周期-卸载阶段" aria-label="Permalink to “生命周期 - 卸载阶段”">​</a></h2><table tabindex="0"><thead><tr><th>钩子函数</th><th>触发时机</th><th>作用</th></tr></thead><tbody><tr><td>componentWillUnmount</td><td>组件卸载（从页面中消失）</td><td>执行清理工作（比如：清理定时器等）</td></tr></tbody></table>`,11)]])}var u=r(c,[[`render`,l]]);export{s as __pageData,u as default};